#include <vector>
#include <queue>
#include <numeric>
#include <unordered_map>

class Solution {
public:
    int earliestSecondToMarkIndices(std::vector<int>& nums, std::vector<int>& changeIndices) {
        int n = nums.size(), m = changeIndices.size();
        long long nums_sum = 0;
        for (int x : nums) nums_sum += x;

        auto can_mark = [&](int max_second) {
            std::unordered_map<int, int> second_to_index;
            for (int s = 0; s < max_second; ++s) {
                int idx = changeIndices[s] - 1;
                if (!second_to_index.count(s) && nums[idx] > 0) {
                    bool seen = false;
                    for (auto const& [sec, i] : second_to_index) if (i == idx) { seen = true; break; }
                    if (!seen) second_to_index[s] = idx;
                }
            }
            std::priority_queue<int, std::vector<int>, std::greater<int>> min_heap;
            int marks = 0;
            for (int s = max_second - 1; s >= 0; --s) {
                if (second_to_index.count(s)) {
                    int index = second_to_index[s];
                    min_heap.push(nums[index]);
                    if (marks == 0) {
                        min_heap.pop();
                        marks++;
                    } else {
                        marks--;
                    }
                } else {
                    marks++;
                }
            }
            long long heap_sum = 0;
            std::vector<int> tmp;
            while (!min_heap.empty()) { heap_sum += min_heap.top(); tmp.push_back(min_heap.top()); min_heap.pop(); }
            int heap_size = tmp.size();
            long long decrement_cost = (nums_sum - heap_sum) + (n - heap_size);
            long long reset_cost = 2LL * heap_size;
            return decrement_cost + reset_cost <= max_second;
        };

        int l = 1, r = m, ans = -1;
        while (l <= r) {
            int mid = l + (r - l) / 2;
            if (can_mark(mid)) {
                ans = mid;
                r = mid - 1;
            } else l = mid + 1;
        }
        return ans;
    }
};

import java.util.*;

class Solution {
    public int earliestSecondToMarkIndices(int[] nums, int[] changeIndices) {
        int n = nums.length, m = changeIndices.length;
        long numsSum = 0;
        for (int x : nums) numsSum += x;

        int l = 1, r = m, ans = -1;
        while (l <= r) {
            int mid = l + (r - l) / 2;
            if (canMark(mid, nums, changeIndices, numsSum)) {
                ans = mid;
                r = mid - 1;
            } else l = mid + 1;
        }
        return ans;
    }

    private boolean canMark(int maxSecond, int[] nums, int[] changeIndices, long numsSum) {
        int n = nums.length;
        Map<Integer, Integer> secondToIndex = new HashMap<>();
        Set<Integer> seen = new HashSet<>();
        for (int s = 0; s < maxSecond; ++s) {
            int idx = changeIndices[s] - 1;
            if (!seen.contains(idx) && nums[idx] > 0) {
                seen.add(idx);
                secondToIndex.put(s, idx);
            }
        }
        PriorityQueue<Integer> minHeap = new PriorityQueue<>();
        int marks = 0;
        for (int s = maxSecond - 1; s >= 0; --s) {
            if (secondToIndex.containsKey(s)) {
                int index = secondToIndex.get(s);
                minHeap.add(nums[index]);
                if (marks == 0) {
                    minHeap.poll();
                    marks++;
                } else {
                    marks--;
                }
            } else {
                marks++;
            }
        }
        long heapSum = 0;
        int heapSize = minHeap.size();
        for (int val : minHeap) heapSum += val;
        long decrementCost = (numsSum - heapSum) + (n - heapSize);
        long resetCost = 2L * heapSize;
        return decrementCost + resetCost <= maxSecond;
    }
}

var earliestSecondToMarkIndices = function(nums, changeIndices) {
    const n = nums.length, m = changeIndices.length;
    let numsSum = 0;
    for (const x of nums) numsSum += x;

    const canMark = (maxSecond) => {
        const secondToIndex = new Map();
        const seen = new Set();
        for (let s = 0; s < maxSecond; ++s) {
            const idx = changeIndices[s] - 1;
            if (!seen.has(idx) && nums[idx] > 0) {
                seen.add(idx);
                secondToIndex.set(s, idx);
            }
        }
        const heap = [];
        let marks = 0;
        for (let s = maxSecond - 1; s >= 0; --s) {
            if (secondToIndex.has(s)) {
                const index = secondToIndex.get(s);
                heap.push(nums[index]);
                heap.sort((a, b) => a - b);
                if (marks === 0) {
                    heap.shift();
                    marks++;
                } else {
                    marks--;
                }
            } else {
                marks++;
            }
        }
        let heapSum = 0;
        for (const v of heap) heapSum += v;
        const heapSize = heap.length;
        const decrementCost = (numsSum - heapSum) + (n - heapSize);
        const resetCost = 2 * heapSize;
        return decrementCost + resetCost <= maxSecond;
    };

    let l = 1, r = m, ans = -1;
    while (l <= r) {
        const mid = Math.floor((l + r) / 2);
        if (canMark(mid)) {
            ans = mid;
            r = mid - 1;
        } else l = mid + 1;
    }
    return ans;
};
